// Locale routing, generated by Babelize and taken over to keep the docs
// English-only until they are translated (Babelize no longer regenerates it).
import { NextResponse, type NextRequest } from "next/server";
import { locales, sourceLocale } from "./i18n/locales";

const ONE_YEAR = 60 * 60 * 24 * 365;

/** Sections that exist in the source language only, served unprefixed. */
const SOURCE_ONLY = ["/docs"];

function isSourceOnly(pathname: string) {
  return SOURCE_ONLY.some((p) => pathname === p || pathname.startsWith(`${p}/`));
}

function localized(pathname: string, locale: string) {
  if (locale === sourceLocale) return pathname;
  return pathname === "/" ? `/${locale}` : `/${locale}${pathname}`;
}

/** hreflang alternates for search engines, as an HTTP Link header. */
function alternates(request: NextRequest, pathname: string) {
  const origin = request.nextUrl.origin;
  const links = locales.map(
    (l) => `<${origin}${localized(pathname, l)}>; rel="alternate"; hreflang="${l}"`,
  );
  links.push(`<${origin}${pathname}>; rel="alternate"; hreflang="x-default"`);
  return links.join(", ");
}

export function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const [, first = "", ...rest] = pathname.split("/");
  const prefixed = locales.find(
    (l) => l !== sourceLocale && l.toLowerCase() === first.toLowerCase(),
  );

  if (prefixed) {
    const url = request.nextUrl.clone();
    url.pathname = `/${rest.join("/")}`;
    // /ja/docs/… → /docs/…: there is no Japanese version yet.
    if (isSourceOnly(url.pathname)) return NextResponse.redirect(url);
    // /ja/pricing is app/pricing, in Japanese.
    const headers = new Headers(request.headers);
    headers.set("x-babelize-locale", prefixed);
    const response = NextResponse.rewrite(url, { request: { headers } });
    response.cookies.set("NEXT_LOCALE", prefixed, { path: "/", maxAge: ONE_YEAR, sameSite: "lax" });
    response.headers.set("Link", alternates(request, url.pathname));
    return response;
  }

  const headers = new Headers(request.headers);
  headers.set("x-babelize-locale", sourceLocale);
  if (isSourceOnly(pathname)) return NextResponse.next({ request: { headers } });

  // An unprefixed URL is the source language, unless the visitor chose another.
  // "/" always stays English, so English is reachable before there is a
  // language switcher to change NEXT_LOCALE.
  const chosen = request.cookies.get("NEXT_LOCALE")?.value;
  if (pathname !== "/" && chosen && chosen !== sourceLocale && locales.includes(chosen)) {
    const url = request.nextUrl.clone();
    url.pathname = localized(pathname, chosen);
    return NextResponse.redirect(url);
  }

  const response = NextResponse.next({ request: { headers } });
  response.headers.set("Link", alternates(request, pathname));
  return response;
}

export const config = {
  // Pages only: not API routes, Next.js internals or files (anything with a dot).
  matcher: ["/((?!api|trpc|_next|_vercel|.*\\..*).*)"],
};
